// Separate checker: no producer modules, Euler oracle, or source implementation.
use std::{collections::{BTreeMap,BTreeSet},fs};
fn pow(mut a:i64,mut n:i64)->i64{let mut v=1;while n>0{if n&1!=0{v=v*a%509;}a=a*a%509;n>>=1;}v}
fn add(a:Option<(i64,i64)>,b:Option<(i64,i64)>)->Option<(i64,i64)>{match(a,b){(None,b)=>b,(a,None)=>a,(Some((x,y)),Some((u,v)))=>{if x==u&&(y+v)%509==0{return None;}let(n,d)=if x==u{(3*x*x+2,2*y)}else{(v-y,u-x)};let m=n.rem_euclid(509)*pow(d.rem_euclid(509),507)%509;let xx=(m*m-x-u).rem_euclid(509);Some((xx,(m*(x-xx)-y).rem_euclid(509)))}}}
fn main(){let args:Vec<String>=std::env::args().collect();assert_eq!(args.len(),4);let mut squares=[false;479];for x in 1..479{squares[x*x%479]=true;}let chi=|x:usize|if x%479==0{0i64}else if squares[x%479]{1}else{-1};
 let mut fibers:BTreeMap<Vec<i64>,Vec<usize>>=BTreeMap::new();for x in 0..479{fibers.entry((0..14).map(|a|chi(x+a)).collect()).or_default().push(x);}
 let terms:Vec<(i64,Vec<usize>)>=fs::read_to_string(&args[1]).unwrap().lines().map(|l|{let(c,s)=l.split_once('\t').unwrap();let c=c.parse().unwrap();assert!((1..479).contains(&c));let labels:Vec<usize>=if s.is_empty(){vec![]}else{s.split(',').map(|x|x.parse().unwrap()).collect()};assert!(labels.len()<=4&&labels.iter().all(|&a|a<14));(c,labels)}).collect();assert_eq!(terms.len(),465);
 let mut rules=BTreeMap::new();for line in fs::read_to_string(&args[2]).unwrap().lines(){let f:Vec<_>=line.split('\t').collect();assert_eq!(f.len(),3);let e=f[0].parse::<usize>().unwrap();let beta=f[1].parse::<i64>().unwrap();let sig:Vec<i64>=f[2].split(',').map(|x|x.parse().unwrap()).collect();assert!((14..16).contains(&e)&&(1..479).contains(&beta));assert_eq!(sig.len(),14);assert!(sig.iter().all(|s|(-1..=1).contains(s)));assert!(rules.insert(sig,(e,beta)).is_none());}assert_eq!(rules.len(),8);
 let(mut requests,mut recovered,mut used)=([0usize;2],vec![0i64;479],BTreeSet::new());for(sig,fiber)in &fibers{let mean=terms.iter().map(|(c,l)|c*l.iter().map(|&a|sig[a]).product::<i64>()).sum::<i64>().rem_euclid(479);assert!(fiber.len()==1||fiber.len()==2);assert_eq!((mean*fiber.len()as i64-fiber.iter().sum::<usize>()as i64).rem_euclid(479),0);
  for &x in fiber{let value=if fiber.len()==2{let &(e,beta)=rules.get(sig).unwrap();assert_ne!(chi(x+e),0);requests[e-14]+=1;used.insert(sig.clone());(mean+beta*chi(x+e)).rem_euclid(479)}else{assert!(!rules.contains_key(sig));mean};assert_eq!(value,x as i64);recovered[x]=value;}}
 assert_eq!(used.len(),8);assert_eq!(requests,[12,4]);
 let mut points=vec![None];for i in 1..479{points.push(add(points[i-1],Some((3,68))));}assert_eq!(add(points[478],Some((3,68))),None);
 let raw=fs::read_to_string(&args[3]).unwrap();let mut lines=raw.lines();assert_eq!(lines.next().unwrap(),"scalar\tx\ty\trecovered\tsign_values\textra_offset\tsteps\tskipped_signs\textra_conversions\tinitial_conversions\tinitial_direct\textra_direct");let mut seen=BTreeSet::new();let(mut extra,mut skips,mut steps)=(0,0,0);for line in lines{let f:Vec<i64>=line.split('\t').map(|x|x.parse().unwrap()).collect();assert_eq!(f.len(),12);assert!((0..479).contains(&f[0]));let x=f[0]as usize;assert!(seen.insert(x));let q=if f[1]==-1&&f[2]==-1{None}else{Some((f[1],f[2]))};assert_eq!(points[x],q);assert_eq!(f[3],recovered[x]);let sig:Vec<_>=(0..14).map(|a|chi(x+a)).collect();let e=rules.get(&sig).map(|&(e,_)|e as i64).unwrap_or(-1);let n=if e<0{0}else{e-13};assert_eq!(&f[4..],&[14+i64::from(e>=0),e,n,if e<0{0}else{e-14},24*n,24*(14-i64::from((0..14).any(|a|(x+a)%479==0))),(0..2).filter(|&a|![0,1,2,478].contains(&((x+a)%479))).count()as i64,0]);extra+=i64::from(e>=0);skips+=f[7];steps+=f[6];}
 let mut expected:BTreeSet<usize>=[0,1,2,478].into_iter().collect();for f in fibers.values().filter(|f|f.len()==2){expected.extend(f);}assert_eq!(seen,expected);assert_eq!((extra,skips,steps),(16,4,20));println!("field_values=479 correction_rules=8 public_points=20 offset14=12 offset15=4 sign_values=6722 geometry_steps=20 skipped_signs=4");}
